export const c12Phy2HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(255, 145, 0, 0.05); border: 1.5px solid #FF9100; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF9100; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary &amp; Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF9100; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Concepts &amp; Key Definitions &bull; Unit II: Current Electricity (JKBOSE / CBSE Official Syllabus)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>1. Electric Current (I):</b>\n        <span style=\"color: #FFFFFF;\">Rate of flow of electric charge: I = dq/dt [Ampere A, Dimensions: [A]]. Scalar quantity.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>2. Drift Velocity (v<sub>d</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Average velocity with which free electrons drift opposite to applied electric field: v<sub>d</sub> = (e E &tau;)/m &approx; 10<sup>-4</sup> m s<sup>-1</sup>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>3. Electron Mobility (&mu;):</b>\n        <span style=\"color: #FFFFFF;\">Drift velocity per unit electric field: &mu; = v<sub>d</sub> / E = (e &tau;)/m [m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup>]. Always positive.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>4. Resistivity (&rho;) &amp; Conductivity (&sigma;):</b>\n        <span style=\"color: #FFFFFF;\">Intrinsic property &rho; = m / (n e<sup>2</sup> &tau;) [&Omega; m], &sigma; = 1/&rho; [S m<sup>-1</sup>]. Independent of shape/size.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>5. Electromotive Force (EMF, E) &amp; Internal Resistance (r):</b>\n        <span style=\"color: #FFFFFF;\">Potential difference across open-circuit cell terminals. Terminal voltage during discharge: V = E - I r.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF9100; border-radius: 6px;\">\n        <b style='color: #FF9100; display: block; margin-bottom: 4px;'>6. Wheatstone Bridge Condition:</b>\n        <span style=\"color: #FFFFFF;\">When galvanometer current I<sub>g</sub> = 0 (null deflection), the balanced arms satisfy P / Q = R / S.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- DIAGRAM 1: CIRCUIT SYMBOLS -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Standard Circuit Symbols of Common Electrical Elements\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Standard schematic symbols for Resistor, Single Cell, Multi-Cell Battery, Ammeter (A), Voltmeter (V), and Variable Resistor / Rheostat.\n    </div>\n  </div>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 30px;\">1. Electric Current, Flow of Electric Charges in Metallic Conductors, Drift Velocity &amp; Mobility</h2>\n\n  <p>Current electricity is the dynamic branch of physics dealing with charges in steady motion. In electrostatics, charges reside at rest on conductors in electrostatic equilibrium. However, when an external electric field or potential difference is maintained across the ends of a metallic conductor by a battery, free electrons experience continuous electrostatic forces, establishing a macroscopic continuous electric current.</p>\n\n  \n  <div style=\"background: rgba(255, 145, 0, 0.08); border-left: 4.5px solid #FF9100; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF9100; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Current (I)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">\n    Electric current across any cross-sectional area of a conductor is defined as the net rate of flow of electric charge passing through that area per unit time:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dq</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> \\quad \\text{(Instantaneous)} \\quad | \\quad I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span> \\quad \\text{(Steady State)}</div>\n    <b>SI Unit:</b> <b>Ampere (A)</b> = 1 Coulomb per second (1 C s<sup>-1</sup>).<br>\n    <b>Nature:</b> Electric current is a <b>scalar quantity</b> because it obeys ordinary scalar algebraic laws of addition rather than vector addition laws.\n  </div>\n  </div>\n\n  <!-- DIAGRAM 2 (IMAGE 1): ELECTRIC CURRENT -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Electric Current (Flow of Electrons & Direction of Current)\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Electric current is the net rate of flow of charge: I = Q / t (Unit: Ampere A). Conventional current flows from high to low potential, opposite to electron flow.\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(i) Flow of Charges in Metallic Conductors &amp; Microscopic Electron Dynamics</h3>\n  <p>In metallic conductors (such as copper, aluminium, and silver), valence electrons detach from positive metal ions to form an abundant free electron gas (number density <i>n &approx; 8.5 &times; 10<sup>28</sup> m<sup>-3</sup></i>). In thermal equilibrium without an external electric field:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Thermal Random Motion:</b> Free electrons move randomly in all directions with high thermal speeds (<i>u<sub>rms</sub> &approx; 10<sup>5</sup> to 10<sup>6</sup> m s<sup>-1</sup></i> at 300 K).</li>\n    <li><b>Zero Net Current:</b> Because velocities are distributed randomly in 3D space, the vector average of thermal velocities across any cross-section is strictly zero: <b>u<sub>avg</sub> = 0</b>.</li>\n  </ul>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(ii) Drift Velocity (v<sub>d</sub>) &amp; Relaxation Time (&tau;)</h3>\n  <p>When a potential difference <i>V</i> is applied across a conductor of length <i>L</i>, an internal electric field <b>E</b> = <i>V / L</i> is established. Each electron of mass <i>m</i> and charge <i>-e</i> experiences an electric force <b>F</b> = <i>-e <b>E</b></i>, acquiring acceleration <b>a</b> = <i>-e <b>E</b> / m</i> opposite to <b>E</b>.</p>\n\n  \n  <div style=\"background: rgba(30, 41, 59, 0.85); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.4);\">\n    <div style=\"color: #FF9100; font-weight: bold; font-size: 16.5px; margin-bottom: 12px; border-bottom: 1px solid rgba(255,145,0,0.3); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Relation Between Drift Velocity, Electric Current &amp; Current Density\n    </div>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.75;\">\n      \n    <b>Step 1 (Drift Velocity Formulation):</b> Let <i>&tau;</i> be the relaxation time (average time between two successive collisions with lattice ions). Starting from zero average thermal velocity:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">\\mathbf{v}_d = \\mathbf{u}_{\\text{avg}} + \\mathbf{a} \\tau = 0 + \\left(-<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e \\mathbf{E}</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span>\\right) \\tau &implies; <b>v_d = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m L</span>\n  </span></b></div>\n\n    <b>Step 2 (Current in Terms of Drift Velocity, I = n e A v_d):</b> In a conductor of length <i>L</i> and cross-sectional area <i>A</i>, total number of free electrons is <i>N = n A L</i>, and total charge is <i>q = n A L e</i>.<br>\n    Time taken for these electrons to drift across length <i>L</i> is <i>t = L / v_d</i>:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n A L e</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L / v_d</span>\n  </span> &implies; <b>I = n e A v_d</b></div>\n\n    <b>Step 3 (Current Density J):</b> Current per unit normal cross-sectional area:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">J = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> = n e v_d = n e \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span>\\right) = \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span>\\right) E = <b>\\sigma E</b></div>\n  \n    </div>\n  </div>\n\n  <!-- DIAGRAM 3 (IMAGE 2): DRIFT VELOCITY & MOBILITY -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Drift Velocity & Electron Mobility\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Free electrons drift through metal lattice ions with small average drift velocity v_d. Current I = n e A v_d, and mobility μ = v_d / E.\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(iii) Electron Mobility (&mu;)</h3>\n  \n  <div style=\"background: rgba(255, 145, 0, 0.08); border-left: 4.5px solid #FF9100; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF9100; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electron Mobility (&mu;)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">\n    <b>Mobility (&mu;):</b> Defined as the magnitude of drift velocity acquired per unit applied electric field:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">\\mu = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v_d</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">E</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span></div>\n    <b>SI Unit:</b> <b>m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></b>.<br>\n    <b>Note:</b> Mobility is always defined as a positive scalar quantity for both electrons (&mu;<sub>e</sub>) and positive hole carriers (&mu;<sub>h</sub>).\n  </div>\n  </div>\n\n  \n  <div style=\"background: rgba(56, 189, 248, 0.08); border-left: 4.5px solid #38BDF8; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #38BDF8; font-size: 16.5px; display: block; margin-bottom: 6px;\">💡 REAL-WORLD INTUITION &amp; ANALOGY: Drift vs Thermal Speed Analogy</b>\n    <div style=\"color: #E2E8F0; font-size: 15.5px; line-height: 1.65;\">\n    Imagine a huge swarm of bees buzzing wildly at 100 km/h in every random direction (thermal velocity ~10<sup>5</sup> m/s). When a gentle breeze starts blowing, the entire swarm slowly drifts forward at 1 cm/s (drift velocity ~10<sup>-4</sup> m/s). That gentle forward drift is electric current!\n  </div>\n  </div>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">2. Ohm's Law, Electrical Resistance &amp; V–I Characteristics</h2>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(i) Ohm's Law &amp; Its Deduction</h3>\n  <p><b>Ohm's Law (1828):</b> <i>At constant temperature and physical dimensions, the steady electric current flowing through a metallic conductor is directly proportional to the potential difference applied across its ends:</i></p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>V &prop; I &nbsp;&implies;&nbsp; V = I R</b></div>\n\n  <!-- DIAGRAM 4 (IMAGE 3): OHM'S LAW -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Ohm's Law Circuit & Principle\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 At constant temperature, electric current I is directly proportional to potential difference V: V = I R.\n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(30, 41, 59, 0.85); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 16px; margin: 20px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.4);\">\n    <div style=\"color: #FF9100; font-weight: bold; font-size: 16.5px; margin-bottom: 12px; border-bottom: 1px solid rgba(255,145,0,0.3); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Deduction of Ohm's Law from Drift Velocity\n    </div>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.75;\">\n      \n    Substitute drift velocity <i>v_d = e V &tau; / (m L)</i> into the current equation <i>I = n e A v_d</i>:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">I = n e A \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m L</span>\n  </span>\\right) = \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> A \\tau</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m L</span>\n  </span>\\right) V &implies; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">I</span>\n  </span> = \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> \\tau</span>\n  </span>\\right) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> = <b>R</b></div>\n    At constant temperature, <i>m, n, e, &tau;</i> are constant for a given conductor, hence <b>R = constant</b>.\n  \n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(ii) V–I Characteristics: Linear (Ohmic) &amp; Non-Linear (Non-Ohmic) Devices</h3>\n  <p>Conductors and electronic devices are classified into two broad categories based on their current-voltage relationships:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Ohmic Conductors:</b> Devices that strictly obey Ohm's law (V &prop; I). The V–I characteristic graph is a perfect straight line passing through the origin. Examples: all metallic conductors (Cu, Al, Ag) under small current/constant temperature.</li>\n    <li><b>Non-Ohmic Devices:</b> Devices for which V is not strictly proportional to I. The V–I characteristic is non-linear, non-symmetric under reversal of voltage polarity, or shows negative dynamic resistance regions. Examples: p-n junction semiconductor diodes, vacuum tubes, thermistors, and GaAs crystals.</li>\n  </ul>\n\n  <!-- DIAGRAM 5 (IMAGE 4): V-I CHARACTERISTICS -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"V–I Characteristics (Linear Ohmic vs Non-Linear Devices)\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 V–I graph is a linear straight line (R = constant) for Ohmic metallic conductors, and non-linear for non-ohmic devices like diodes and vacuum tubes.\n    </div>\n  </div>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">3. Electrical Resistivity, Conductivity, Temperature Dependence &amp; Combinations of Resistors</h2>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(i) Electrical Resistivity (&rho;) and Conductivity (&sigma;)</h3>\n  <p>The electrical resistance <i>R</i> of a uniform conductor is directly proportional to its length <i>L</i> and inversely proportional to its cross-sectional area <i>A</i>:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">R = \\rho <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A</span>\n  </span> &implies; <b>\\rho = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R A</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">L</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> \\tau</span>\n  </span></b></div>\n\n  <p><b>Electrical Conductivity (&sigma;):</b> The reciprocal of resistivity: <b>&sigma; = 1 / &rho; = (n e<sup>2</sup> &tau;) / m</b> [SI Unit: Siemens per meter, S m<sup>-1</sup> or &Omega;<sup>-1</sup> m<sup>-1</sup>].</p>\n\n  <!-- DIAGRAM 6 (IMAGE 5): RESISTIVITY AND CONDUCTIVITY -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Electrical Resistivity & Conductivity of a Conductor\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Resistance of cylindrical conductor of length L and area A: R = ρ L / A. Conductivity σ = 1 / ρ (Unit: S m⁻¹).\n    </div>\n  </div>\n\n  <!-- DIAGRAM 7 (IMAGE 15): RESISTIVITY OF MATERIALS TABLE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Resistivity of Standard Conducting & Resistance Materials\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Representative resistivity values at room temperature: Silver (1.6 × 10⁻⁸ Ω m), Copper (1.7 × 10⁻⁸ Ω m), Aluminium (2.8 × 10⁻⁸ Ω m), Tungsten (5.6 × 10⁻⁸ Ω m), and Nichrome alloy (1.1 × 10⁻⁶ Ω m).\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(ii) Temperature Dependence of Resistance &amp; Resistivity</h3>\n  <p>As temperature rises, lattice ions vibrate more vigorously, increasing collision frequency and reducing relaxation time <i>&tau;</i>. Since <i>&rho; &prop; 1/&tau;</i>, resistance increases with temperature:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>R_T = R_0 (1 + \\alpha \\Delta T) \\quad | \\quad \\rho_T = \\rho_0 (1 + \\alpha \\Delta T)</b></div>\n\n  <p>where <i>&alpha;</i> is the <b>temperature coefficient of resistance</b>: <i>&alpha; = (R_T - R_0) / (R_0 &Delta;T)</i> [SI Unit: K<sup>-1</sup> or &deg;C<sup>-1</sup>].</p>\n\n  <!-- DIAGRAM 8 (IMAGE 6): TEMPERATURE DEPENDENCE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Temperature Dependence of Resistance\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Resistance increases linearly with temperature for metals (α > 0) according to R_T = R₀(1 + αΔT), while remaining almost independent for standard alloys (α ≈ 0).\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(iii) Combinations of Resistors (Series &amp; Parallel)</h3>\n  <ul style=\"margin: 6px 0 6px 18px; line-height: 1.8;\">\n    <li><b>Series Combination:</b> Current <i>I</i> is identical across all resistors, voltages add up:\n      <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>R_s = R_1 + R_2 + R_3 + ... + R_n</b></div>\n    </li>\n    <li><b>Parallel Combination:</b> Potential difference <i>V</i> is identical across all branches, currents add up:\n      <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R_p</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R_1</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R_2</span>\n  </span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R_3</span>\n  </span> + ... + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R_n</span>\n  </span></b></div>\n    </li>\n  </ul>\n\n  <!-- DIAGRAM 9 (IMAGE 7): RESISTORS IN SERIES & PARALLEL -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Resistors in Series and Parallel Combinations\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Series: R_s = R₁ + R₂ + R₃ (same current, voltages add). Parallel: 1/R_p = 1/R₁ + 1/R₂ + 1/R₃ (same voltage, currents add).\n    </div>\n  </div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">4. Electrical Energy, Electrical Power &amp; Joule's Heating Effect</h2>\n\n  <p>When a current <i>I</i> passes through a resistor of resistance <i>R</i> maintained across a potential difference <i>V</i> for time <i>t</i>, the battery does work <i>W = q V = (I t) V</i>. This work is converted into thermal heat energy in the resistor:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>H = W = V I t = I<sup>2</sup> R t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup> t</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R</span>\n  </span></b> \\quad \\text{[Joule J]}</div>\n\n  <p><b>Electrical Power (P):</b> Rate at which electrical energy is consumed or dissipated:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">W</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span> = V I = I<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R</span>\n  </span></b> \\quad \\text{[Watt W = J s<sup>-1</sup>]}</div>\n\n  <!-- DIAGRAM 10 (IMAGE 14): ELECTRICAL ENERGY AND POWER -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Electrical Energy & Electrical Power\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Electrical power dissipated in resistor: P = V I = I² R = V² / R (Unit: Watt W). Total electrical heat energy: H = P t = V I t (Unit: Joule J).\n    </div>\n  </div>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">5. Electromotive Force (EMF), Internal Resistance &amp; Terminal Potential Difference</h2>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(i) Cell with Internal Resistance &amp; Circuit Equation</h3>\n  <p>The finite resistance offered by the electrolyte and electrodes of a cell to the internal flow of current is its <b>internal resistance (r)</b>. For a cell of EMF <i>E</i> supplying current <i>I</i> to an external load resistor <i>R</i>:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>V = E - I r &implies; I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">E</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R + r</span>\n  </span> &implies; r = \\left(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">E</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V</span>\n  </span> - 1\\right) R</b></div>\n\n  <!-- DIAGRAM 11 (IMAGE 8): CELL WITH INTERNAL RESISTANCE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Cell with Internal Resistance & Terminal Voltage\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Real electrochemical cell of EMF E with internal resistance r connected to external resistor R: Terminal potential difference V = E - I r.\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(ii) EMF vs Terminal Potential Difference</h3>\n  <p><b>Electromotive Force (EMF, E):</b> The maximum potential difference across the terminals of a cell in an <b>open circuit</b> (no current drawn, <i>I = 0 &implies; V = E</i>).<br>\n  <b>Terminal Voltage (V):</b> The potential difference between cell terminals during <b>closed circuit discharge</b> (current drawn, <i>V = E - I r &lt; E</i>).</p>\n\n  <!-- DIAGRAM 12 (IMAGE 9): EMF AND TERMINAL VOLTAGE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"EMF vs Terminal Voltage (Open vs Closed Circuit)\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Electromotive Force (EMF E) is the terminal potential difference in an open circuit (no current). When current flows (closed circuit), terminal voltage V < E.\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">6. Kirchhoff's Rules, Wheatstone Bridge Principle &amp; Meter Bridge</h2>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(i) Kirchhoff's Two Laws</h3>\n  \n  <div style=\"background: rgba(255, 145, 0, 0.08); border-left: 4.5px solid #FF9100; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF9100; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Kirchhoff's Laws</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">\n    <b>1. Kirchhoff's First Rule (Junction Rule / KCL):</b> The algebraic sum of all currents meeting at any electrical junction is zero:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\">\\Sigma I_{\\text{in}} = \\Sigma I_{\\text{out}} &implies; <b>\\Sigma I = 0</b></div>\n    <i>(Direct manifestation of the Law of Conservation of Electric Charge).</i><br><br>\n    <b>2. Kirchhoff's Second Rule (Loop Rule / KVL):</b> The algebraic sum of potential changes (&Delta;V) around any closed loop is zero:\n    <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>\\Sigma \\Delta V = \\Sigma E + \\Sigma (I R) = 0</b></div>\n    <i>(Direct manifestation of the Law of Conservation of Energy).</i>\n  </div>\n  </div>\n\n  <!-- DIAGRAM 13 (IMAGE 10): KIRCHHOFF'S RULES -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Kirchhoff's Rules (Junction Rule & Loop Rule)\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Junction Rule (KCL): Net incoming current equals outgoing current (Σ I = 0, charge conservation). Loop Rule (KVL): Algebraic sum of potential changes around any closed loop is zero (Σ ΔV = 0, energy conservation).\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(ii) Wheatstone Bridge Principle</h3>\n  <p>The Wheatstone bridge consists of four resistors <i>P, Q, R, S</i> arranged in a bridge network with a central galvanometer <i>G</i>. At null balance (no deflection, <i>I<sub>g</sub> = 0</i>):</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Q</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">S</span>\n  </span></b></div>\n\n  <!-- DIAGRAM 14 (IMAGE 11): WHEATSTONE BRIDGE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Wheatstone Bridge Principle & Balance Condition\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Bridge network of 4 resistors P, Q, R, S and central galvanometer G. At balance (null deflection G = 0): P / Q = R / S.\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF9100; margin-top: 24px;\">(iii) Meter Bridge (Slide Wire Practical Bridge)</h3>\n  <p>The <b>meter bridge</b> is the practical laboratory apparatus based on the balanced Wheatstone bridge principle, using a 1-meter uniform resistance wire and a sliding jockey. When balanced at balancing length <i>l</i> cm from the left zero end:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 145, 0, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">X</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">100 - l</span>\n  </span> &implies; X = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">100 - l</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">l</span>\n  </span> R</b></div>\n\n  <!-- DIAGRAM 15 (IMAGE 12): METER BRIDGE -->\n  \n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 10px; padding: 14px 16px; margin: 22px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 420px;\">\n      <img src=\"data:image/jpeg;base64,\" style=\"width: 100%; max-width: 380px; height: auto; display: block; border-radius: 6px;\" alt=\"Meter Bridge (Practical Form of Wheatstone Bridge)\" />\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 10px; line-height: 1.5; font-weight: 500;\">\n      💡 Slide wire meter bridge of 1 m uniform resistance wire with sliding jockey. At null point length l: R / X = l / (100 - l), enabling precise measurement of unknown resistance X.\n    </div>\n  </div>\n\n  <!-- SECTION 7 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">7. Master Comparison Matrices</h2>\n\n  <div style=\"overflow-x: auto; margin: 20px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; text-align: left; font-size: 15px; background: #0B0F19; border-radius: 8px; overflow: hidden; border: 1px solid rgba(255,145,0,0.3);\">\n      <thead>\n        <tr style=\"background: rgba(255,145,0,0.25); color: #FF9100; font-weight: bold; border-bottom: 2px solid #FF9100;\">\n          <th style=\"padding: 12px 14px; border-right: 1px solid rgba(255,255,255,0.1);\">Property</th>\n          <th style=\"padding: 12px 14px; border-right: 1px solid rgba(255,255,255,0.1);\">Resistance (R)</th>\n          <th style=\"padding: 12px 14px;\">Resistivity (&rho;)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FFD54F; border-right: 1px solid rgba(255,255,255,0.1);\">Definition</td>\n          <td style=\"padding: 10px 14px; border-right: 1px solid rgba(255,255,255,0.1);\">Opposition to current flow in a conductor</td>\n          <td style=\"padding: 10px 14px;\">Resistance of unit cube of material</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08); background: rgba(255,255,255,0.02);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FFD54F; border-right: 1px solid rgba(255,255,255,0.1);\">Dependence on Geometry</td>\n          <td style=\"padding: 10px 14px; color: #4ADE80; font-weight: bold; border-right: 1px solid rgba(255,255,255,0.1);\">Depends on Length &amp; Area (R &prop; L/A)</td>\n          <td style=\"padding: 10px 14px; color: #FDE047; font-weight: bold;\">Independent of Length &amp; Area</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FFD54F; border-right: 1px solid rgba(255,255,255,0.1);\">SI Unit</td>\n          <td style=\"padding: 10px 14px; border-right: 1px solid rgba(255,255,255,0.1);\">Ohm (&Omega;)</td>\n          <td style=\"padding: 10px 14px;\">Ohm-meter (&Omega; m)</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FFD54F; border-right: 1px solid rgba(255,255,255,0.1);\">Temperature Effect</td>\n          <td style=\"padding: 10px 14px; border-right: 1px solid rgba(255,255,255,0.1);\">Increases with temperature in metals</td>\n          <td style=\"padding: 10px 14px;\">Increases with temperature in metals</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- SECTION 8 -->\n  <h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 36px;\">8. Master Revision Formula Cheat Sheet</h2>\n\n  <div style=\"background: rgba(255, 145, 0, 0.05); border: 1.5px solid rgba(255, 145, 0, 0.4); border-radius: 12px; padding: 18px; margin: 20px 0;\">\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.8;\">\n      <b>1. Current &amp; Drift Dynamics:</b><br>\n      - Current: I = q/t = dq/dt = n e A v<sub>d</sub>.<br>\n      - Drift velocity: v<sub>d</sub> = (e E &tau;)/m = (e V &tau;)/(m L).<br>\n      - Mobility: &mu; = v<sub>d</sub>/E = (e &tau;)/m.<br>\n      - Current density: J = I/A = n e v<sub>d</sub> = &sigma; E.<br><br>\n\n      <b>2. Resistivity, Resistance &amp; Temperature:</b><br>\n      - Resistance: R = &rho; L / A = [ m / (n e<sup>2</sup> &tau;) ] (L / A).<br>\n      - Resistivity: &rho; = m / (n e<sup>2</sup> &tau;) &nbsp;|&nbsp; Conductivity: &sigma; = 1/&rho; = n e<sup>2</sup> &tau; / m.<br>\n      - Temperature dependence: R<sub>T</sub> = R<sub>0</sub> (1 + &alpha; &Delta;T).<br>\n      - Series: R<sub>s</sub> = &Sigma; R<sub>i</sub> &nbsp;|&nbsp; Parallel: 1/R<sub>p</sub> = &Sigma; 1/R<sub>i</sub>.<br><br>\n\n      <b>3. Cells, Power &amp; Networks:</b><br>\n      - Power: P = V I = I<sup>2</sup> R = V<sup>2</sup> / R &nbsp;|&nbsp; Heat: H = I<sup>2</sup> R t.<br>\n      - Discharging cell: V = E - I r &nbsp;|&nbsp; Charging cell: V = E + I r.<br>\n      - Internal resistance: r = R [ (E/V) - 1 ].<br>\n      - Kirchhoff's Laws: &Sigma; I = 0 (Junction) &nbsp;|&nbsp; &Sigma; &Delta;V = 0 (Loop).<br>\n      - Wheatstone Bridge (null condition): P / Q = R / S.<br>\n      - Meter Bridge: R / X = l / (100 - l) &implies; X = R (100 - l) / l.\n    </div>\n  </div>\n\n</div>\n";

export const c12Phy2HtmlSolutions = "<div style=\"padding: 12px; color: #FFFFFF; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n<h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 15px; margin-bottom: 20px;\">SECTION A: Very Short Answer Questions (1 Mark Each) — Q1 to Q40</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q1: Define electric current and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electric current is the net rate of flow of electric charge across any cross-section of a conductor: I = dq / dt. Its SI unit is the <b>Ampere (A)</b> [1 A = 1 Coulomb per second (C s<sup>-1</sup>)].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q2: Why is electric current considered a scalar quantity even though it is assigned a direction in circuits?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electric current is a scalar quantity because it obeys the ordinary algebraic laws of addition rather than the laws of vector addition (e.g. triangle or parallelogram law of vectors).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q3: Define one Ampere of electric current in terms of rate of charge flow.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">One Ampere is the steady electric current that flows through a conductor when a net charge of one Coulomb passes across any cross-section of the conductor in one second (1 A = 1 C s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q4: State the dimensional formula of electric current and electric charge.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Dimensional formula of Electric Current: <b>[M<sup>0</sup> L<sup>0</sup> T<sup>0</sup> A<sup>1</sup>]</b>.<br>Dimensional formula of Electric Charge: q = I t &rArr; <b>[M<sup>0</sup> L<sup>0</sup> T<sup>1</sup> A<sup>1</sup>]</b> = [A T].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q5: What is the typical order of magnitude of drift velocity of free electrons in a current-carrying metallic wire?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The typical order of magnitude of drift velocity of electrons under ordinary electric fields is <b>10<sup>-4</sup> m s<sup>-1</sup></b> (approx 0.1 to 1 mm s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q6: What is the approximate order of magnitude of random thermal speed of free electrons in a metal at room temperature (300 K)?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The random thermal speed of electrons at room temperature is of the order of <b>10<sup>5</sup> to 10<sup>6</sup> m s<sup>-1</sup></b> (approx 100 to 1000 km s<sup>-1</sup>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q7: Define relaxation time of free electrons in a metallic conductor.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Relaxation time (&#964;) is the average time interval elapsed between two successive collisions of a drifting free electron with the heavy positive metal lattice ions. Typical value: &#964; &approx; 10<sup>-14</sup> s.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q8: Write the mathematical expression for drift velocity in terms of electric field, charge, mass, and relaxation time.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>, where e is electron charge, E is electric field intensity, &#964; is relaxation time, and m is mass of electron (m &approx; 9.11 &times; 10<sup>-31</sup> kg).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q9: Define electron mobility and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electron mobility (&#956;) is defined as the magnitude of drift velocity acquired per unit applied electric field: &#956; = v<sub>d</sub> / E = (e &#964;) / m. Its SI unit is <b>m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q10: State the dimensional formula of electron mobility.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Mobility &#956; = [L T<sup>-1</sup>] / [M L T<sup>-3</sup> A<sup>-1</sup>] = <b>[M<sup>-1</sup> L<sup>0</sup> T<sup>2</sup> A<sup>1</sup>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q11: How does the drift velocity of free electrons change if the potential difference across a conductor of length L is doubled?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since v<sub>d</sub> = (e V &#964;) / (m L), drift velocity is directly proportional to potential difference V (v<sub>d</sub> &prop; V). Doubling V <b>doubles the drift velocity</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q12: A potential difference V is applied across a wire of length L. If the length is doubled keeping V constant, what happens to drift velocity?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since v<sub>d</sub> = (e V &#964;) / (m L), v<sub>d</sub> &prop; 1/L for constant V. When length is doubled, drift velocity is <b>halved (v<sub>d</sub>' = v<sub>d</sub> / 2)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q13: State Ohm's law in scalar form.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Ohm's Law states that at constant temperature and physical conditions, the electric current (I) through a conductor is directly proportional to the potential difference (V) across its ends: <b>V = I R</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q14: State Ohm's law in vector microscopic form and define each term.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b><b>j</b> = &#963; <b>E</b> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span> <b>E</b></b>, where <b>j</b> is current density vector, &#963; is electrical conductivity, &#961; is electrical resistivity, and <b>E</b> is electric field vector.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q15: Define electrical resistance of a conductor and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical resistance (R) is the physical property of a conductor by virtue of which it opposes the flow of electric current through it: R = V / I. Its SI unit is <b>Ohm (&Omega;) = 1 Volt per Ampere (V A<sup>-1</sup>)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q16: State the dimensional formula of electrical resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">R = V / I = [W / q] / I = [M L<sup>2</sup> T<sup>-2</sup>] / [A<sup>2</sup> T] = <b>[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-2</sup>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q17: Define electrical resistivity (specific resistance) of a material.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical resistivity (&#961;) is the electrical resistance offered by a unit cube of the material of a conductor across its opposite faces: &#961; = R A / L. It is an intrinsic property of the material.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q18: State the SI unit and dimensional formula of electrical resistivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">SI Unit: <b>Ohm-meter (&Omega; m)</b>.<br>Dimensional Formula: [&#961;] = [R] [A] / [L] = [M<sup>1</sup> L<sup>3</sup> T<sup>-3</sup> A<sup>-2</sup>].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q19: Define electrical conductivity and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical conductivity (&#963;) is the reciprocal of electrical resistivity: &#963; = 1 / &#961;. Its SI unit is <b>Siemens per meter (S m<sup>-1</sup>) or &Omega;<sup>-1</sup> m<sup>-1</sup> (mho m<sup>-1</sup>)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q20: How does the electrical resistivity of a typical metallic conductor (like copper) vary with temperature?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Resistivity of metals <b>increases with temperature</b> (&#961;<sub>T</sub> = &#961;<sub>0</sub>[1 + &alpha;(T - T<sub>0</sub>)]) because rising temperature increases lattice vibrations, reducing the electron relaxation time &#964;.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q21: Why does the resistivity of semiconductors (like Silicon or Germanium) decrease rapidly with increase in temperature?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">In semiconductors, rising temperature breaks covalent bonds, causing charge carrier density n to increase exponentially, which overcomes the decrease in &#964; and causes resistivity to drop exponentially.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q22: Name two alloys having very high resistivity and nearly zero temperature coefficient of resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Manganin</b> (Cu: 84%, Mn: 12%, Ni: 4%) and <b>Constantan / Eureka</b> (Cu: 55%, Ni: 45%).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q23: Why are standard resistance coils and potentiometer wires made of Manganin or Constantan rather than pure copper?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Because Manganin and Constantan possess high electrical resistivity and an almost negligible temperature coefficient of resistance (&alpha; &approx; 10<sup>-5</sup> K<sup>-1</sup>), maintaining constant resistance during heating.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q24: What is a superconductor and what is its resistance below critical temperature T<sub>c</sub>?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">A superconductor is a material whose electrical resistance drops strictly to <b>zero (R = 0, &#961; = 0)</b> when cooled below a characteristic critical transition temperature T<sub>c</sub> (e.g. Mercury at 4.2 K).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q25: Give three distinct examples of non-Ohmic conductors or devices.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. P-N Junction Diode, 2. Light Emitting Diode (LED) / Transistor, 3. Gallium Arsenide (GaAs) / Electrolyte.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q26: Define dynamic (differential) resistance of a non-linear electrical circuit element.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Dynamic resistance (r<sub>d</sub>) is defined as the ratio of a small change in potential difference (&Delta;V) to the corresponding small change in current (&Delta;I) in the non-linear operating region: <b>r<sub>d</sub> = &Delta;V / &Delta;I</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q27: Name one semiconductor material that displays negative dynamic resistance in its V-I characteristic curve.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Gallium Arsenide (GaAs)</b> (used in high-frequency microwave Gunn diodes).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q28: Define electrical power and write its three standard mathematical expressions in terms of V, I, and R.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Electrical power (P) is the rate at which electrical energy is consumed or converted into other forms of energy: <b>P = V I = I<sup>2</sup> R = V<sup>2</sup> / R</b>. SI unit: <b>Watt (W)</b> [1 W = 1 J s<sup>-1</sup>].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q29: Express 1 Kilowatt-hour (1 kWh) of electrical energy in standard SI units (Joules).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1 kWh = 1 kW &times; 1 hour = 1000 W &times; 3600 s = <b>3.6 &times; 10<sup>6</sup> Joules (3.6 MJ)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q30: State Joule's Law of Heating for a resistor.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The heat (H) generated in a conductor of resistance R carrying current I for time t is directly proportional to: (1) square of current (I<sup>2</sup>), (2) resistance (R), and (3) time (t): <b>H = I<sup>2</sup> R t Joules</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q31: Between two bulbs rated (220 V, 60 W) and (220 V, 100 W), which bulb has higher filament resistance?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Since resistance R = V<sup>2</sup> / P, resistance is inversely proportional to rated power (R &prop; 1/P). Therefore, the <b>60 W bulb has higher filament resistance</b> [R<sub>60</sub> &approx; 807 &Omega; vs R<sub>100</sub> &approx; 484 &Omega;].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q32: Define Electromotive Force (EMF, &#949;) of an electrochemical cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">EMF of a cell is the maximum potential difference between its two terminals when the cell is in an <b>open circuit</b> (drawing zero external current, I = 0): &#949; = dW / dq. SI Unit: <b>Volt (V)</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q33: State the dimensional formula of EMF of a cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">[&#949;] = [Work / Charge] = [M L<sup>2</sup> T<sup>-2</sup>] / [A T] = <b>[M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]</b> (identical to electric potential).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q34: Define internal resistance of a primary electrochemical cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Internal resistance (r) is the electrical resistance offered by the chemical electrolyte and electrodes inside the cell to the flow of internal ionic current.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q35: State the physical condition under which the terminal potential difference V of a cell is strictly equal to its EMF &#949;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the circuit is <b>open</b> (no current is drawn from the cell, I = 0) or when the internal resistance of the cell is strictly zero (ideal cell).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q36: Can the terminal potential difference across a cell ever exceed its EMF? If yes, under what condition?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Yes</b>, when the cell is being <b>charged</b> by an external DC source. During charging, current enters the positive terminal and <b>V = &#949; + I r</b> (V &gt; &#949;).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q37: What is the terminal potential difference and current when a cell of EMF &#949; and internal resistance r is short-circuited (R = 0)?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Terminal potential difference <b>V = 0</b>; Short-circuit current reaches maximum value: <b>I<sub>max</sub> = &#949; / r</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q38: State Kirchhoff's Junction Rule (KCL) and name the universal conservation law on which it is based.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">At any circuit node or junction, the algebraic sum of currents entering and leaving is strictly zero: <b>&Sigma; I = 0</b>. It is based on the <b>Law of Conservation of Electric Charge</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q39: State Kirchhoff's Loop Rule (KVL) and name the universal conservation law on which it is based.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The algebraic sum of changes in potential around any closed mesh loop in an electrical network is zero: <b>&Sigma; &Delta;V = 0 (&Sigma; &#949; = &Sigma; I R)</b>. It is based on the <b>Law of Conservation of Energy</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q40: State the mathematical balance condition for a Wheatstone bridge consisting of resistors P, Q, R, and S.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the galvanometer shows null deflection (zero current I<sub>g</sub> = 0), the bridge is balanced: <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span><span style=\"padding: 0 2px; display: inline-block;\">Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">S</span></span></b>.</div>\n    </div>\n  </div>\n<h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 35px; margin-bottom: 20px;\">SECTION B: Short Answer Questions (2 &amp; 3 Marks Each) — Q41 to Q80</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q41: Derive the expression for drift velocity of free electrons in terms of relaxation time: v<sub>d</sub> = (e E &#964;) / m.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let an electron experience electric field <b>E</b>. Force <b>F</b> = -e <b>E</b>, acceleration <b>a</b> = -e <b>E</b> / m.<br>If thermal velocity after last collision is <b>u<sub>i</sub></b> and time elapsed is t<sub>i</sub>, velocity <b>v<sub>i</sub></b> = <b>u<sub>i</sub></b> + <b>a</b> t<sub>i</sub>.<br>Taking average over N electrons: <b>v<sub>d</sub></b> = (1/N)&Sigma;<b>v<sub>i</sub></b> = (1/N)&Sigma;<b>u<sub>i</sub></b> + <b>a</b> [(1/N)&Sigma;t<sub>i</sub>].<br>Since average thermal velocity (1/N)&Sigma;<b>u<sub>i</sub></b> = 0 and average time is relaxation time &#964;, we get <b><b>v<sub>d</sub></b> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e <b>E</b> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>. Magnitude: <b>v<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q42: Derive the relation between macroscopic electric current I and microscopic drift velocity v<sub>d</sub>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Consider a conductor of length L, cross-sectional area A, with free electron density n.<br>Total volume = A L. Total number of free electrons = n A L.<br>Total charge contained = q = (n A L) e.<br>Time taken by electrons to drift across length L is t = L / v<sub>d</sub>.<br>Current <b>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span><span style=\"padding: 0 2px; display: inline-block;\">t</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(n A L) e</span><span style=\"padding: 0 2px; display: inline-block;\">L / v<sub>d</sub></span></span> = n e A v<sub>d</sub></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q43: Derive the relation between current density <b>j</b>, conductivity &#963;, and electric field <b>E</b>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using I = n e A v<sub>d</sub>, current density j = I / A = n e v<sub>d</sub>.<br>Substitute v<sub>d</sub> = (e E &#964;) / m:<br>j = n e [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e E &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span>] E.<br>Since electrical conductivity &#963; = (n e<sup>2</sup> &#964;) / m, we get <b>j = &#963; E</b> (or <b>E = &#961; j</b>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q44: Why does an electric bulb glow almost instantaneously when switched on, even though drift velocity of electrons is only ~10<sup>-4</sup> m s<sup>-1</sup>?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When the circuit switch is closed, an electromagnetic field is set up across the entire circuit almost instantaneously at the speed of light (c &approx; 3 &times; 10<sup>8</sup> m s<sup>-1</sup>). Free electrons throughout the entire length of the wire, including the filament, begin drifting simultaneously at the very same instant, lighting the bulb immediately.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q45: A wire of resistance R is stretched uniformly such that its length is doubled. Find its new resistance and resistivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Resistivity:</b> Resistivity &#961; is an intrinsic material property and remains <b>strictly unchanged (&#961;' = &#961;)</b>.<br>2. <b>Resistance:</b> When stretched to L' = 2 L, volume V = A L remains constant &rArr; A' = A / 2.<br>New resistance R' = &#961; L' / A' = &#961; (2 L) / (A / 2) = 4 (&#961; L / A) = <b>4 R</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q46: A wire of resistance 16 &Omega; is stretched uniformly until its radius is halved. Find its new resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When radius r' = r / 2, area A' = &pi;(r/2)<sup>2</sup> = A / 4.<br>Since volume V = A L = constant, length becomes L' = 4 L.<br>New resistance R' = &#961; L' / A' = &#961; (4 L) / (A / 4) = 16 (&#961; L / A) = 16 R = 16 &times; 16 = <b>256 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q47: Calculate the relaxation time in copper if electron density is 8.5 &times; 10<sup>28</sup> m<sup>-3</sup> and resistivity is 1.7 &times; 10<sup>-8</sup> &Omega; m. (m = 9.1 &times; 10<sup>-31</sup> kg, e = 1.6 &times; 10<sup>-19</sup> C).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using &#961; = m / (n e<sup>2</sup> &#964;) &rArr; &#964; = m / (n e<sup>2</sup> &#961;):<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / [(8.5 &times; 10<sup>28</sup>) &times; (1.6 &times; 10<sup>-19</sup>)<sup>2</sup> &times; (1.7 &times; 10<sup>-8</sup>)]<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / [8.5 &times; 10<sup>28</sup> &times; 2.56 &times; 10<sup>-38</sup> &times; 1.7 &times; 10<sup>-8</sup>]<br>&#964; = (9.1 &times; 10<sup>-31</sup>) / (3.70 &times; 10<sup>-17</sup>) = <b>2.46 &times; 10<sup>-14</sup> s</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q48: Explain the physical cause of electrical resistance in metallic conductors on the basis of electron collisions.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">When an electric field is applied, free electrons accelerate and gain kinetic energy. However, during their drift, they continually collide with the heavy positive metal ions vibrating in the crystal lattice. In each collision, electrons lose their directed drift kinetic energy to the lattice as thermal vibrational energy. This continuous opposition and momentum transfer due to collisions constitutes electrical resistance.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q49: Deduce the formula for electrical resistivity in terms of electron mass, charge, density, and relaxation time: &#961; = m / (n e<sup>2</sup> &#964;).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">From drift theory, I = n e A v<sub>d</sub> = n e A [(e V &#964;) / (m L)] = [(n e<sup>2</sup> &#964; A) / (m L)] V.<br>Rearranging: V / I = [m / (n e<sup>2</sup> &#964;)] (L / A).<br>Comparing with Ohm's law R = V / I = &#961; (L / A), we obtain: <b>&#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q50: Sketch and explain the resistivity vs temperature (&#961; vs T) graphs for: (a) Copper (metal), (b) Silicon (semiconductor), (c) Nichrome (alloy).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Copper (Metal):</b> &#961; increases with T (non-linear at low T, linear at room T) as lattice collisions reduce &#964;.<br>2. <b>Silicon (Semiconductor):</b> &#961; decreases exponentially with T as thermal energy generates abundant electron-hole pairs.<br>3. <b>Nichrome (Alloy):</b> &#961; is high with very weak linear positive slope (&alpha; is very small).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q51: The resistance of a platinum wire is 5.00 &Omega; at 0 &deg;C and 5.79 &Omega; at 100 &deg;C. When inserted in a hot bath, resistance is 6.15 &Omega;. Find bath temperature.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Temperature coefficient &alpha; = (R<sub>100</sub> - R<sub>0</sub>) / (R<sub>0</sub> &times; 100) = (5.79 - 5.00) / (5.00 &times; 100) = 0.79 / 500 = 1.58 &times; 10<sup>-3</sup> &deg;C<sup>-1</sup>.<br>For bath temperature t: t = [(R<sub>t</sub> - R<sub>0</sub>) / (R<sub>0</sub> &alpha;)] = (6.15 - 5.00) / (5.00 &times; 1.58 &times; 10<sup>-3</sup>) = 1.15 / (7.90 &times; 10<sup>-3</sup>) = <b>145.57 &deg;C &approx; 145.6 &deg;C</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q52: Distinguish clearly between Ohmic and Non-Ohmic conductors with illustrative examples and graphs.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Ohmic Conductors:</b> Obey V = I R strictly. V-I graph is a straight line through origin with constant slope (e.g. Copper wire, metals).<br>2. <b>Non-Ohmic Conductors:</b> Violate V = I R. V-I graph is non-linear, non-symmetrical, or possesses negative slope regions (e.g. P-N junction diode, vacuum tube, GaAs, thyristor).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q53: In a forward-biased p-n junction diode, a voltage change from 0.70 V to 0.75 V increases current from 10 mA to 35 mA. Calculate dynamic resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">&Delta;V = 0.75 V - 0.70 V = 0.05 V.<br>&Delta;I = 35 mA - 10 mA = 25 mA = 25 &times; 10<sup>-3</sup> A = 0.025 A.<br>Dynamic resistance <b>r<sub>d</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&Delta;V</span><span style=\"padding: 0 2px; display: inline-block;\">&Delta;I</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">0.05 V</span><span style=\"padding: 0 2px; display: inline-block;\">0.025 A</span></span> = 2.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q54: Explain why electrical power is transmitted over long distances from generating stations at extremely high voltages.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let power to be transmitted be P at voltage V through transmission cables of resistance R<sub>c</sub>.<br>Current in line I = P / V.<br>Power lost as heat in transmission line: <b>P<sub>loss</sub> = I<sup>2</sup> R<sub>c</sub> = (P / V)<sup>2</sup> R<sub>c</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P<sup>2</sup> R<sub>c</sub></span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span></span></b>.<br>Since P<sub>loss</sub> &prop; 1/V<sup>2</sup>, transmitting at ultra-high voltages dramatically minimizes I<sup>2</sup> R heat losses and conductor thickness required.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q55: Two bulbs rated (220 V, 40 W) and (220 V, 100 W) are connected in series to 220 V supply. Which bulb glows brighter and why?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Filament resistance R = V<sup>2</sup> / P. R<sub>40</sub> = (220)<sup>2</sup> / 40 = 1210 &Omega;; R<sub>100</sub> = (220)<sup>2</sup> / 100 = 484 &Omega;.<br>In series, current I is same for both. Power consumed P = I<sup>2</sup> R &prop; R.<br>Since R<sub>40</sub> &gt; R<sub>100</sub>, the <b>40 W bulb dissipates more power and glows brighter</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q56: Two bulbs rated (220 V, 40 W) and (220 V, 100 W) are connected in parallel to 220 V supply. Which bulb glows brighter and why?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">In parallel, voltage V = 220 V is identical across both bulbs.<br>Power consumed P = V<sup>2</sup> / R &prop; 1/R &prop; P<sub>rated</sub>.<br>Since 100 W bulb has lower resistance (R<sub>100</sub> = 484 &Omega; vs R<sub>40</sub> = 1210 &Omega;), the <b>100 W bulb dissipates 100 W and glows brighter</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q57: An electric kettle has two heating coils. One boils water in 10 minutes, the other in 15 minutes. Find boiling time if connected in: (a) series, (b) parallel.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let heat required be H at voltage V. H = (V<sup>2</sup>/R<sub>1</sub>) t<sub>1</sub> &rArr; R<sub>1</sub> = V<sup>2</sup> t<sub>1</sub> / H; R<sub>2</sub> = V<sup>2</sup> t<sub>2</sub> / H.<br><b>(a) Series:</b> R<sub>s</sub> = R<sub>1</sub> + R<sub>2</sub> &rArr; <b>t<sub>s</sub> = t<sub>1</sub> + t<sub>2</sub> = 10 + 15 = 25 minutes</b>.<br><b>(b) Parallel:</b> 1/R<sub>p</sub> = 1/R<sub>1</sub> + 1/R<sub>2</sub> &rArr; <b>t<sub>p</sub> = (t<sub>1</sub> t<sub>2</sub>) / (t<sub>1</sub> + t<sub>2</sub>) = (10 &times; 15) / (10 + 15) = 150 / 25 = 6 minutes</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q58: State any four distinct points of difference between Electromotive Force (EMF) and Terminal Potential Difference of a cell.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Definition:</b> EMF is max work done across entire circuit; PD is work done between two circuit points.<br>2. <b>Circuit Condition:</b> EMF measured in open circuit (I=0); PD measured in closed circuit (I&gt;0).<br>3. <b>Load Dependence:</b> EMF is independent of load R; PD depends directly on R.<br>4. <b>Magnitude:</b> EMF &gt; PD during discharge (V = &#949; - I r).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q59: State the factors upon which the internal resistance of an electrochemical cell depends.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Electrode Separation (d):</b> r &prop; d (increases with distance between plates).<br>2. <b>Electrode Area (A):</b> r &prop; 1/A (decreases with larger immersed surface area).<br>3. <b>Electrolyte Concentration (C):</b> r increases with higher concentration.<br>4. <b>Temperature (T):</b> r decreases as temperature increases (increases ionic mobility).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q60: For a cell of EMF &#949; and internal resistance r, sketch: (a) V vs R graph, (b) V vs I graph.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>V vs R Graph:</b> V = &#949; R / (R + r). Starts from origin (0,0), curves upwards and asymptotically approaches V = &#949; as R &rarr; &infin;.<br>2. <b>V vs I Graph:</b> V = &#949; - I r. Straight line with negative slope (-r) having y-intercept &#949; (at I=0) and x-intercept I<sub>sc</sub> = &#949;/r (at V=0).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q61: Derive the formula for internal resistance of a cell: r = R [(&#949; / V) - 1].</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let cell of EMF &#949; and internal resistance r be connected across load R.<br>Current I = &#949; / (R + r).<br>Terminal potential difference V = I R &rArr; I = V / R.<br>Equating both: V / R = &#949; / (R + r) &rArr; (R + r) / R = &#949; / V &rArr; 1 + (r / R) = &#949; / V.<br><b>r / R = (&#949; / V) - 1 &nbsp;&rArr;&nbsp; r = R [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;</span><span style=\"padding: 0 2px; display: inline-block;\">V</span></span> - 1]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q62: A battery of EMF 10 V and internal resistance 3 &Omega; is connected to a resistor. If current is 0.5 A, find: (a) external resistance R, (b) terminal voltage V.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) External Resistance R:</b><br>I = &#949; / (R + r) &rArr; 0.5 = 10 / (R + 3) &rArr; R + 3 = 10 / 0.5 = 20 &rArr; <b>R = 17 &Omega;</b>.<br><br><b>(b) Terminal Voltage V:</b><br>V = &#949; - I r = 10 - (0.5 &times; 3) = 10 - 1.5 = <b>8.5 V</b> (or V = I R = 0.5 &times; 17 = 8.5 V).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q63: When a 2 &Omega; resistor is connected to a cell, current is 0.5 A. When a 5 &Omega; resistor is connected, current is 0.25 A. Find EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">From I = &#949; / (R + r):<br>Case 1: &#949; = 0.5 (2 + r) = 1.0 + 0.5 r &nbsp;--- (1)<br>Case 2: &#949; = 0.25 (5 + r) = 1.25 + 0.25 r &nbsp;--- (2)<br>Equating (1) and (2): 1.0 + 0.5 r = 1.25 + 0.25 r &rArr; 0.25 r = 0.25 &rArr; <b>r = 1.0 &Omega;</b>.<br>Substitute r into (1): &#949; = 1.0 + 0.5(1.0) = <b>1.5 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q64: State Maximum Power Transfer Theorem and prove that power delivered to load R is maximum when R = r.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Statement:</b> Maximum power is transferred from a source of EMF &#949; and internal resistance r to an external load R when load resistance equals internal resistance (R = r).<br><br><b>Proof:</b> P = I<sup>2</sup> R = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;</span><span style=\"padding: 0 2px; display: inline-block;\">R + r</span></span>]<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> R</span><span style=\"padding: 0 2px; display: inline-block;\">(R + r)<sup>2</sup></span></span>.<br>For maximum power, dP/dR = 0 &rArr; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">d</span><span style=\"padding: 0 2px; display: inline-block;\">dR</span></span> [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">(R+r)<sup>2</sup></span></span>] = 0 &rArr; (R+r)<sup>2</sup>(1) - R[2(R+r)] = 0 &rArr; (R+r) - 2R = 0 &rArr; <b>R = r</b>.<br>Maximum power value: <b>P<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">4 r</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q65: Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> are connected in series. Find equivalent EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let current I flow through series cells from terminals A to C via B.<br>V<sub>A</sub> - V<sub>B</sub> = &#949;<sub>1</sub> - I r<sub>1</sub>; &nbsp; V<sub>B</sub> - V<sub>C</sub> = &#949;<sub>2</sub> - I r<sub>2</sub>.<br>Total PD V<sub>AC</sub> = (V<sub>A</sub> - V<sub>B</sub>) + (V<sub>B</sub> - V<sub>C</sub>) = (&#949;<sub>1</sub> + &#949;<sub>2</sub>) - I (r<sub>1</sub> + r<sub>2</sub>).<br>Comparing with V<sub>AC</sub> = &#949;<sub>eq</sub> - I r<sub>eq</sub>:<br><b>&#949;<sub>eq</sub> = &#949;<sub>1</sub> + &#949;<sub>2</sub> &nbsp;|&nbsp; r<sub>eq</sub> = r<sub>1</sub> + r<sub>2</sub></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q66: Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> are connected in parallel. Find equivalent EMF and internal resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Let total current I = I<sub>1</sub> + I<sub>2</sub>.<br>Terminal voltage V = &#949;<sub>1</sub> - I<sub>1</sub> r<sub>1</sub> &rArr; I<sub>1</sub> = (&#949;<sub>1</sub> - V) / r<sub>1</sub>; &nbsp; I<sub>2</sub> = (&#949;<sub>2</sub> - V) / r<sub>2</sub>.<br>I = [(&#949;<sub>1</sub> - V) / r<sub>1</sub>] + [(&#949;<sub>2</sub> - V) / r<sub>2</sub>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>] - V [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>].<br>Rearranging for V: <b>&#949;<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> &nbsp;|&nbsp; r<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">r<sub>1</sub> r<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q67: State the sign convention rules for applying Kirchhoff's Loop Rule (KVL).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Resistor IR drop:</b> When traversing in the direction of assumed loop current, potential drops: <b>&Delta;V = - I R</b>. If traversing opposite to current, potential rises: <b>&Delta;V = + I R</b>.<br>2. <b>EMF Source:</b> When traversing from negative to positive terminal (inside battery), potential rises: <b>&Delta;V = + &#949;</b>. When traversing from positive to negative terminal, potential drops: <b>&Delta;V = - &#949;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q68: Explain how Kirchhoff's First Law and Second Law illustrate universal conservation laws.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>First Law (Junction Rule):</b> Electric charge cannot accumulate indefinitely at a junction in steady state. Rate of charge entering = Rate of charge leaving (&Sigma; I = 0), manifesting <b>Conservation of Charge</b>.<br>2. <b>Second Law (Loop Rule):</b> Electrostatic force is conservative, so work done in taking charge around closed loop is zero (&oint; <b>E</b> &sdot; d<b>l</b> = 0), manifesting <b>Conservation of Energy</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q69: In a bridge circuit, P = 10 &Omega;, Q = 20 &Omega;, R = 15 &Omega;, S = 30 &Omega;. Is the bridge balanced? Find galvanometer current.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check ratio: P / Q = 10 / 20 = 1/2; &nbsp; R / S = 15 / 30 = 1/2.<br>Since <b>P / Q = R / S = 1/2</b>, the Wheatstone bridge is perfectly balanced.<br>Potential at B equals potential at D (V<sub>B</sub> = V<sub>D</sub>). Current through galvanometer <b>I<sub>g</sub> = 0 A</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q70: State two advantages of null deflection methods (e.g. Wheatstone bridge) over direct deflection methods with ammeters and voltmeters.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. At null point (I<sub>g</sub> = 0), zero current is drawn from the circuit, eliminating loading errors and internal resistance voltage drops.<br>2. The measurement does not depend on galvanometer calibration or scale accuracy, depending only on the accuracy of standard known resistors.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q71: When is a Wheatstone bridge most sensitive? Explain.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">A Wheatstone bridge is most sensitive when all four arm resistances (P, Q, R, S) are nearly equal (of the same order of magnitude). In this condition, a tiny fractional variation in unknown resistance produces the maximum detectable galvanometer deflection.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q72: In a balanced Wheatstone bridge, if the battery and galvanometer are interchanged, does the balance condition remain satisfied? Justify.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>Yes, the bridge remains balanced.</b> The battery and galvanometer branches form conjugate arms. Mathematically, P/Q = R/S is algebraically equivalent to P/R = Q/S, which is the balance condition when positions are interchanged.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q73: A uniform wire of resistance 20 &Omega; is bent into a circle. Find effective resistance between two diametrically opposite points.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">The two semicircular halves are in parallel. Each half has resistance R<sub>1</sub> = R<sub>2</sub> = 20 / 2 = 10 &Omega;.<br>Effective resistance <b>R<sub>eff</sub> = (R<sub>1</sub> R<sub>2</sub>) / (R<sub>1</sub> + R<sub>2</sub>) = (10 &times; 10) / (10 + 10) = 100 / 20 = 5 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q74: A uniform wire of resistance 12 &Omega; is bent to form an equilateral triangle ABC. Find equivalent resistance between vertices A and B.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Each of the 3 equal sides has resistance 12 / 3 = 4 &Omega;.<br>Between A and B, side AB (4 &Omega;) is in parallel with the series combination of sides AC and CB (4 + 4 = 8 &Omega;).<br><b>R<sub>AB</sub> = (4 &times; 8) / (4 + 8) = 32 / 12 = 8 / 3 &Omega; = 2.67 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q75: A carbon resistor has color bands: Yellow, Violet, Brown, Gold. Determine its resistance value and tolerance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Color values: Yellow = 4, Violet = 7, Multiplier Brown = 10<sup>1</sup>, Tolerance Gold = &plusmn; 5%.<br>Resistance value: <b>R = 47 &times; 10<sup>1</sup> &Omega; &plusmn; 5% = 470 &Omega; &plusmn; 5%</b> [Range: 446.5 &Omega; to 493.5 &Omega;].</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q76: A carbon resistor has color bands: Red, Red, Orange, Silver. Determine its resistance value and tolerance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Color values: Red = 2, Red = 2, Multiplier Orange = 10<sup>3</sup>, Tolerance Silver = &plusmn; 10%.<br>Resistance value: <b>R = 22 &times; 10<sup>3</sup> &Omega; &plusmn; 10% = 22 k&Omega; &plusmn; 10%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q77: Find equivalent resistance between A and B for a bridge having P = 2 &Omega;, Q = 4 &Omega;, R = 4 &Omega;, S = 8 &Omega;, and central resistor 5 &Omega;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check balance condition: P / Q = 2 / 4 = 1/2; &nbsp; R / S = 4 / 8 = 1/2.<br>Since P / Q = R / S, bridge is balanced. Zero current flows through central 5 &Omega; resistor (it can be removed).<br>Branch ACB = 2 + 4 = 6 &Omega;; Branch ADB = 4 + 8 = 12 &Omega; in parallel.<br><b>R<sub>AB</sub> = (6 &times; 12) / (6 + 12) = 72 / 18 = 4.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q78: A 10 m potentiometer wire has resistance 20 &Omega;. It is connected in series with a 6 V battery and 10 &Omega; resistor. Find potential gradient k.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Total circuit resistance R<sub>total</sub> = 20 + 10 = 30 &Omega;.<br>Current in wire I = &#949; / R<sub>total</sub> = 6 / 30 = 0.2 A.<br>Potential drop across wire V<sub>wire</sub> = I &times; R<sub>wire</sub> = 0.2 &times; 20 = 4.0 V.<br>Potential gradient <b>k = V<sub>wire</sub> / L = 4.0 V / 10 m = 0.40 V m<sup>-1</sup> = 0.004 V cm<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q79: State two primary physical reasons why Nichrome alloy is chosen as heating element in electric irons and toasters.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>High Electrical Resistivity:</b> Enables generation of large Joule heat (H &prop; R) in a compact element length.<br>2. <b>High Melting Point & Non-Oxidizing:</b> Does not oxidize or burn even at red-hot temperatures (~1000 &deg;C).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q80: Why are laboratory connecting wires chosen to be made of thick copper with negligible resistance?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Copper has exceptionally high electrical conductivity (low &#961;), and large cross-sectional area A further reduces resistance (R = &#961; L / A &approx; 0). This prevents unwanted potential drops and power loss in external leads during experiments.</div>\n    </div>\n  </div>\n<h2 style=\"color: #FF9100; border-bottom: 2px solid #FF9100; padding-bottom: 6px; margin-top: 35px; margin-bottom: 20px;\">SECTION C: Long Answer Derivations &amp; Complex Numericals (5 Marks Each) — Q81 to Q100</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q81: Define drift velocity and relaxation time. Deduce Ohm's law from fundamental electron dynamics and derive formulas for resistivity and conductivity.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Definitions:</b><br>• Drift velocity (v<sub>d</sub>): Constant average velocity acquired by free electrons opposite to applied electric field <b>E</b>.<br>• Relaxation time (&#964;): Average time interval between two successive electron collisions.<br><br><b>2. Derivation of v<sub>d</sub>:</b><br>Acceleration <b>a</b> = -e <b>E</b> / m. Velocity <b>v<sub>i</sub></b> = <b>u<sub>i</sub></b> + <b>a</b> t<sub>i</sub>.<br>Average <b>v<sub>d</sub></b> = (1/N)&Sigma;<b>v<sub>i</sub></b> = (1/N)&Sigma;<b>u<sub>i</sub></b> + <b>a</b> [(1/N)&Sigma;t<sub>i</sub>] = 0 - (e <b>E</b> &#964; / m) = - (e <b>E</b> &#964; / m).<br>Magnitude: <b>v<sub>d</sub> = (e E &#964;) / m = (e V &#964;) / (m L)</b>.<br><br><b>3. Electric Current Expression:</b><br>I = n e A v<sub>d</sub> = n e A [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">e V &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964; A</span><span style=\"padding: 0 2px; display: inline-block;\">m L</span></span>] V.<br><br><b>4. Ohm's Law Deduction:</b><br>V / I = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span>] <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">A</span></span> = Constant = R &rArr; <b>V = I R</b>.<br><br><b>5. Resistivity &amp; Conductivity:</b><br>Comparing with R = &#961; L / A: <b>&#961; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span><span style=\"padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span></span></b> &nbsp;|&nbsp; <b>&#963; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&#961;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n e<sup>2</sup> &#964;</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q82: Draw a neat circuit diagram of Wheatstone bridge. Using Kirchhoff's rules, derive the balance condition P / Q = R / S. Explain conjugate arms.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Circuit Setup:</b> Resistors P, Q, R, S form arms AB, BC, AD, DC. Galvanometer G connected across BD, battery &#949; across AC.<br><br><b>2. Applying Kirchhoff's Junction Law:</b><br>At node B: I<sub>1</sub> = I<sub>g</sub> + I<sub>Q</sub> &rArr; I<sub>Q</sub> = I<sub>1</sub> - I<sub>g</sub>.<br>At node D: I<sub>2</sub> + I<sub>g</sub> = I<sub>S</sub> &rArr; I<sub>S</sub> = I<sub>2</sub> + I<sub>g</sub>.<br><br><b>3. Applying Kirchhoff's Loop Law:</b><br>• Mesh ABDA: - I<sub>1</sub> P - I<sub>g</sub> G + I<sub>2</sub> R = 0 &rArr; I<sub>1</sub> P + I<sub>g</sub> G = I<sub>2</sub> R &nbsp;--- (1)<br>• Mesh BCDB: - (I<sub>1</sub> - I<sub>g</sub>) Q + (I<sub>2</sub> + I<sub>g</sub>) S + I<sub>g</sub> G = 0 &nbsp;--- (2)<br><br><b>4. Null Deflection Condition (I<sub>g</sub> = 0):</b><br>When V<sub>B</sub> = V<sub>D</sub>, I<sub>g</sub> = 0.<br>From (1): I<sub>1</sub> P = I<sub>2</sub> R.<br>From (2): I<sub>1</sub> Q = I<sub>2</sub> S.<br>Dividing: (I<sub>1</sub> P) / (I<sub>1</sub> Q) = (I<sub>2</sub> R) / (I<sub>2</sub> S) &rArr; <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P</span><span style=\"padding: 0 2px; display: inline-block;\">Q</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R</span><span style=\"padding: 0 2px; display: inline-block;\">S</span></span></b>.<br><br><b>5. Conjugate Arms:</b> Battery across AC and Galvanometer across BD can be interchanged without changing the null condition because P/Q = R/S is algebraically identical to P/R = Q/S.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q83: Derive expressions for equivalent EMF and internal resistance of two cells connected in parallel. Generalize to n identical cells.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Setup:</b> Two cells of EMFs &#949;<sub>1</sub>, &#949;<sub>2</sub> and internal resistances r<sub>1</sub>, r<sub>2</sub> connected in parallel between points A and B.<br>Let currents supplied be I<sub>1</sub> and I<sub>2</sub> &rArr; Total current I = I<sub>1</sub> + I<sub>2</sub>.<br><br><b>2. Terminal Voltage Formulation:</b><br>V = &#949;<sub>1</sub> - I<sub>1</sub> r<sub>1</sub> &rArr; I<sub>1</sub> = (&#949;<sub>1</sub> - V) / r<sub>1</sub>.<br>V = &#949;<sub>2</sub> - I<sub>2</sub> r<sub>2</sub> &rArr; I<sub>2</sub> = (&#949;<sub>2</sub> - V) / r<sub>2</sub>.<br><br><b>3. Total Current:</b><br>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> - V</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub> - V</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span> = [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>] - V [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span>].<br><br><b>4. Rearranging for V:</b><br>V = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> - I [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">r<sub>1</sub> r<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span>].<br>Comparing with V = &#949;<sub>eq</sub> - I r<sub>eq</sub>:<br><b>&#949;<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>1</sub> r<sub>2</sub> + &#949;<sub>2</sub> r<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub> + r<sub>2</sub></span></span> &nbsp;|&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>eq</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">r<sub>2</sub></span></span></b>.<br><br><b>5. n Identical Cells:</b> For n cells each of EMF &#949; and r: <b>&#949;<sub>eq</sub> = &#949;</b>, &nbsp; <b>r<sub>eq</sub> = r / n</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q84: For mixed grouping of m rows with n cells in each row across load R, derive total current and prove max current occurs when R = n r / m.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Total Number of Cells:</b> N = m &times; n.<br><b>2. Equivalent EMF:</b> Each row has n series cells &rArr; EMF = n &#949;. With m rows in parallel &rArr; <b>&#949;<sub>eq</sub> = n &#949;</b>.<br><b>3. Equivalent Internal Resistance:</b> Each row has resistance n r. With m rows in parallel &rArr; <b>r<sub>eq</sub> = n r / m</b>.<br><b>4. Total Circuit Current:</b><br>I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sub>eq</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R + r<sub>eq</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">R + (n r / m)</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">m R + n r</span></span>.<br><br><b>5. Condition for Maximum Current:</b><br>Denominator m R + n r = (&radic;(m R) - &radic;(n r))<sup>2</sup> + 2&radic;(m n R r).<br>Current I is maximum when (&radic;(m R) - &radic;(n r))<sup>2</sup> = 0 &rArr; &radic;(m R) = &radic;(n r) &rArr; m R = n r &rArr; <b>R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n r</span><span style=\"padding: 0 2px; display: inline-block;\">m</span></span> = r<sub>eq</sub></b>.<br>Max current: <b>I<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">2 R</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m &#949;</span><span style=\"padding: 0 2px; display: inline-block;\">2 r</span></span></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q85: In a circuit network, two batteries of 12 V (r=1 &Omega;) and 6 V (r=2 &Omega;) are connected in parallel across load 4 &Omega;. Find branch currents and terminal voltage using Kirchhoff's rules.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Circuit Setup:</b> Node A connects positive terminals. Let battery 1 deliver I<sub>1</sub>, battery 2 deliver I<sub>2</sub>, load current I = I<sub>1</sub> + I<sub>2</sub>.<br><br><b>2. Loop 1 (Battery 1 and Load):</b><br>12 - 1(I<sub>1</sub>) - 4(I<sub>1</sub> + I<sub>2</sub>) = 0 &rArr; 5 I<sub>1</sub> + 4 I<sub>2</sub> = 12 &nbsp;--- (1)<br><br><b>3. Loop 2 (Battery 2 and Load):</b><br>6 - 2(I<sub>2</sub>) - 4(I<sub>1</sub> + I<sub>2</sub>) = 0 &rArr; 4 I<sub>1</sub> + 6 I<sub>2</sub> = 6 &nbsp;&rArr;&nbsp; 2 I<sub>1</sub> + 3 I<sub>2</sub> = 3 &nbsp;--- (2)<br><br><b>4. Solving Simultaneous Equations:</b><br>Multiply (1) by 3: 15 I<sub>1</sub> + 12 I<sub>2</sub> = 36.<br>Multiply (2) by 4: 8 I<sub>1</sub> + 12 I<sub>2</sub> = 12.<br>Subtract: 7 I<sub>1</sub> = 24 &rArr; <b>I<sub>1</sub> = 24 / 7 A &approx; 3.43 A</b>.<br>From (2): 2(24/7) + 3 I<sub>2</sub> = 3 &rArr; 3 I<sub>2</sub> = 3 - 48/7 = -27/7 &rArr; <b>I<sub>2</sub> = -9 / 7 A &approx; -1.29 A</b> (Battery 2 is actually being charged!).<br><br><b>5. Load Current &amp; Voltage:</b><br>I = I<sub>1</sub> + I<sub>2</sub> = 24/7 - 9/7 = <b>15 / 7 A &approx; 2.14 A</b>.<br>Terminal Voltage V = I R = (15/7) &times; 4 = <b>60 / 7 V &approx; 8.57 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q86: A heating element connected to 230 V draws initial current 3.2 A settling to 2.8 A. If room temp is 27.0 &deg;C and &alpha; = 1.70 &times; 10<sup>-4</sup> &deg;C<sup>-1</sup>, find steady temperature.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. Resistance at room temp T<sub>0</sub> = 27.0 &deg;C: R<sub>0</sub> = V / I<sub>0</sub> = 230 / 3.2 = 71.875 &Omega;.<br>2. Resistance at steady state T: R<sub>T</sub> = V / I = 230 / 2.8 = 82.143 &Omega;.<br>3. Using R<sub>T</sub> = R<sub>0</sub> [1 + &alpha; (T - T<sub>0</sub>)]:<br>T - T<sub>0</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R<sub>T</sub> - R<sub>0</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>0</sub> &alpha;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">82.143 - 71.875</span><span style=\"padding: 0 2px; display: inline-block;\">71.875 &times; 1.70 &times; 10<sup>-4</sup></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">10.268</span><span style=\"padding: 0 2px; display: inline-block;\">0.01221875</span></span> &approx; 840.3 &deg;C.<br>4. Steady temperature: T = 27.0 + 840.3 = <b>867.3 &deg;C</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q87: Twelve identical resistors each of resistance R form a skeleton cube. Find equivalent resistance across body diagonal corners.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Symmetry &amp; Current Division:</b> Let current 6I enter corner A and leave opposite body diagonal corner G.<br>• At A, current divides equally into 3 edges (AB, AD, AE): current = 2I each.<br>• At nodes B, D, E, each 2I divides into 2 edges: current = I each (6 edges carry I).<br>• At nodes C, F, H, currents recombine into 3 edges leading to G: current = 2I each.<br><br><b>2. Potential Drop along Path A &rarr; B &rarr; C &rarr; G:</b><br>V<sub>AG</sub> = (2I) R + (I) R + (2I) R = 5 I R.<br><br><b>3. Equivalent Resistance:</b><br>Total current entered = 6I.<br>V<sub>AG</sub> = (6I) R<sub>eq</sub> &rArr; 5 I R = 6 I R<sub>eq</sub> &rArr; <b>R<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">5</span><span style=\"padding: 0 2px; display: inline-block;\">6</span></span> R</b>.<br>(For face diagonal corners: R<sub>face</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3</span><span style=\"padding: 0 2px; display: inline-block;\">4</span></span> R; along edge: R<sub>edge</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">7</span><span style=\"padding: 0 2px; display: inline-block;\">12</span></span> R).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q88: Derive power output P(R) for battery (&#949;, r). Prove max power occurs at R = r, find P<sub>max</sub>, and calculate electrical efficiency.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Power Output:</b> Current I = &#949; / (R + r). Power delivered to load P = I<sup>2</sup> R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> R</span><span style=\"padding: 0 2px; display: inline-block;\">(R + r)<sup>2</sup></span></span>.<br><b>2. Maximization:</b> dP/dR = 0 &rArr; (R+r)<sup>2</sup> - 2R(R+r) = 0 &rArr; <b>R = r</b>.<br><b>3. Maximum Power:</b> <b>P<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup> r</span><span style=\"padding: 0 2px; display: inline-block;\">(2r)<sup>2</sup></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&#949;<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">4 r</span></span></b>.<br><b>4. Electrical Efficiency at P<sub>max</sub>:</b><br>Total power generated by cell P<sub>total</sub> = &#949; I = &#949; [&#949; / 2r] = &#949;<sup>2</sup> / 2r.<br>Efficiency &eta; = P<sub>load</sub> / P<sub>total</sub> = [&#949;<sup>2</sup> / 4r] / [&#949;<sup>2</sup> / 2r] = 1/2 = <b>50%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q89: A Cu wire (L=2 m, A=10<sup>-6</sup> m<sup>2</sup>, n=8.5 &times; 10<sup>28</sup> m<sup>-3</sup>, &#961;=1.7 &times; 10<sup>-8</sup> &Omega; m) carries 2 A. Find: (a) v<sub>d</sub>, (b) &#964;, (c) E, (d) &#956;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Drift Velocity:</b> v<sub>d</sub> = I / (n e A) = 2.0 / [(8.5 &times; 10<sup>28</sup>)(1.6 &times; 10<sup>-19</sup>)(10<sup>-6</sup>)] = 2.0 / 1.36 &times; 10<sup>4</sup> = <b>1.47 &times; 10<sup>-4</sup> m s<sup>-1</sup></b>.<br><b>(b) Relaxation Time:</b> &#964; = m / (n e<sup>2</sup> &#961;) = (9.1 &times; 10<sup>-31</sup>) / [(8.5 &times; 10<sup>28</sup>)(1.6 &times; 10<sup>-19</sup>)<sup>2</sup>(1.7 &times; 10<sup>-8</sup>)] = <b>2.46 &times; 10<sup>-14</sup> s</b>.<br><b>(c) Electric Field:</b> E = V / L = (I R) / L = (I &#961; L / A) / L = (I &#961;) / A = (2 &times; 1.7 &times; 10<sup>-8</sup>) / 10<sup>-6</sup> = <b>0.034 V m<sup>-1</sup></b>.<br><b>(d) Mobility:</b> &#956; = v<sub>d</sub> / E = (1.47 &times; 10<sup>-4</sup>) / 0.034 = <b>4.32 &times; 10<sup>-3</sup> m<sup>2</sup> V<sup>-1</sup> s<sup>-1</sup></b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q90: Discuss deviations from Ohm's law in p-n diodes, thyristors, and GaAs. Explain negative dynamic resistance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. <b>Non-Linearity in P-N Diode:</b> Asymmetric conduction; exponential current rise in forward bias (I &approx; I<sub>0</sub>(e<sup>eV/k<sub>B</sub>T</sup> - 1)) and tiny saturation current in reverse bias.<br>2. <b>Thyristor:</b> Four-layer p-n-p-n device with distinct forward blocking, negative resistance, and high-conduction on states.<br>3. <b>Negative Dynamic Resistance in GaAs:</b> Due to transfer of electrons from high-mobility lower energy valley to low-mobility upper energy conduction valley at threshold fields (~3 kV/cm). In this region, dI/dV &lt; 0. Utilized in Gunn diode microwave oscillators.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q91: An unbalanced bridge has P=1 &Omega;, Q=2 &Omega;, R=2 &Omega;, S=4 &Omega;, and galvanometer G=5 &Omega; across BD, battery 2 V across AC. Find branch currents.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Using loop analysis with loop currents I<sub>1</sub> (mesh ABDA) and I<sub>2</sub> (mesh BCDB):<br>P=1 &Omega;, Q=2 &Omega;, R=2 &Omega;, S=4 &Omega;. Notice P/Q = 1/2 and R/S = 2/4 = 1/2!<br>Here P/Q = R/S = 1/2, so the bridge is actually <b>BALANCED</b>!<br>Current through galvanometer <b>I<sub>g</sub> = 0 A</b>.<br>Arm ACB resistance = 1 + 2 = 3 &Omega; &rArr; I<sub>ACB</sub> = 2 V / 3 &Omega; = <b>0.67 A</b>.<br>Arm ADB resistance = 2 + 4 = 6 &Omega; &rArr; I<sub>ADB</sub> = 2 V / 6 &Omega; = <b>0.33 A</b>.<br>Total battery current I = 0.67 + 0.33 = <b>1.0 A</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q92: An electric heater on 220 V draws 10 A to heat 50 kg water from 20 &deg;C to 80 &deg;C at 80% efficiency. Find: (a) resistance, (b) time taken, (c) cost at ₹6.00/kWh.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Resistance:</b> R = V / I = 220 V / 10 A = <b>22 &Omega;</b>.<br><b>(b) Power &amp; Heat Required:</b><br>Input Power P = V I = 220 &times; 10 = 2200 W = 2.2 kW.<br>Heat required Q = m c &Delta;T = 50 kg &times; 4200 J kg<sup>-1</sup> K<sup>-1</sup> &times; (80 - 20) = 50 &times; 4200 &times; 60 = 12.6 &times; 10<sup>6</sup> J.<br>Useful heat = &eta; &times; P &times; t &rArr; 12.6 &times; 10<sup>6</sup> = 0.80 &times; 2200 &times; t &rArr; 1760 t = 12.6 &times; 10<sup>6</sup> &rArr; <b>t = 7159 s &approx; 1.99 hours</b>.<br><b>(c) Cost of Energy:</b><br>Energy consumed = P &times; t = 2.2 kW &times; 1.9886 h = 4.375 kWh units.<br>Cost = 4.375 &times; ₹6.00 = <b>₹ 26.25</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q93: A cell of EMF 12 V (r=2 &Omega;) is tested under: (a) Open circuit, (b) Load R=10 &Omega;, (c) Charging at 2 A by 16 V source. Find terminal voltage in each case.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>(a) Open Circuit (I = 0):</b><br>V = &#949; = <b>12.0 V</b>.<br><br><b>(b) Connected to Load R = 10 &Omega; (Discharging):</b><br>Current I = &#949; / (R + r) = 12 / (10 + 2) = 1.0 A.<br>Terminal voltage V = &#949; - I r = 12 - (1.0 &times; 2) = <b>10.0 V</b>.<br><br><b>(c) Charging by external source at I = 2.0 A:</b><br>Terminal voltage V = &#949; + I r = 12 + (2.0 &times; 2) = <b>16.0 V</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q94: State the principle of a potentiometer. Why is it preferred over a voltmeter for measuring EMF of a cell?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Principle of Potentiometer:</b> When a steady current flows through a wire of uniform cross-sectional area and composition, the potential drop across any length L of the wire is directly proportional to that length: <b>V &prop; L &rArr; V = k L</b>, where k = V/L is potential gradient.<br><br><b>2. Why preferred over Voltmeter:</b><br>A voltmeter draws a small finite current to show deflection, measuring terminal voltage V = &#949; - Ir (less than true EMF). A potentiometer works on the <b>null deflection method</b> drawing zero current from the test cell at balance point, acting like an ideal voltmeter with infinite resistance to measure the exact true EMF.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q95: Explain with circuit diagram how a potentiometer is used to find internal resistance of a cell. Derive r = R [(l<sub>1</sub> - l<sub>2</sub>) / l<sub>2</sub>].</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Working:</b><br>• With key K open, cell is in open circuit. Null point is obtained at length l<sub>1</sub> &rArr; <b>&#949; = k l<sub>1</sub></b>.<br>• With key K closed across shunt resistor R, current is drawn. Null point shifts to length l<sub>2</sub> &rArr; <b>V = k l<sub>2</sub></b>.<br><br><b>2. Derivation:</b><br>Dividing the two equations: &#949; / V = (k l<sub>1</sub>) / (k l<sub>2</sub>) = l<sub>1</sub> / l<sub>2</sub>.<br>Substitute into internal resistance formula r = R [(&#949;/V) - 1]:<br><b>r = R [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">l<sub>1</sub> - l<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">l<sub>2</sub></span></span>]</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q96: Prove that when a wire of resistance R is stretched such that length increases by x% (x <= 5%), resistance increases by 2x%. Solve for length increase of 0.2%.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">1. Resistance R = &#961; L / A = &#961; L<sup>2</sup> / V (since Volume V = A L = constant).<br>Taking natural log: ln R = ln(&#961;/V) + 2 ln L.<br>Differentiating: &Delta;R / R = 2 (&Delta;L / L).<br>Multiplying by 100: <b>% Change in R = 2 &times; (% Change in L) = 2x%</b>.<br><br>2. For length increase of 0.2%: % increase in R = 2 &times; 0.2% = <b>0.40%</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q97: Derive Joule's heating law H = I<sup>2</sup> R t. Prove transmitting power P over line R<sub>c</sub> at voltage V reduces power loss by 1/V<sup>2</sup>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Derivation of H:</b> Work done in moving charge q through potential difference V is W = V q = V (I t) = (I R) (I t) = <b>I<sup>2</sup> R t Joules</b>.<br><br><b>2. Transmission Power Loss:</b><br>Current transmitted I = P / V.<br>Power lost as heat in line cables P<sub>loss</sub> = I<sup>2</sup> R<sub>c</sub> = (P / V)<sup>2</sup> R<sub>c</sub> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P<sup>2</sup> R<sub>c</sub></span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup></span></span></b>.<br>If transmission voltage is stepped up by a factor of k (V' = k V), power loss becomes P'<sub>loss</sub> = P<sub>loss</sub> / k<sup>2</sup>, dramatically minimizing energy waste.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q98: Find equivalent resistance between A and B for a symmetric 5-resistor bridge network with P=R=2 &Omega;, Q=S=4 &Omega;, and central resistor 10 &Omega;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\">Check balance ratio: P / Q = 2 / 4 = 1/2; &nbsp; R / S = 2 / 4 = 1/2.<br>Since P/Q = R/S = 1/2, bridge is balanced. Potential at central nodes is equal, zero current flows through 10 &Omega; resistor.<br>Upper branch ACB = 2 + 4 = 6 &Omega;.<br>Lower branch ADB = 2 + 4 = 6 &Omega;.<br>Both branches are in parallel: <b>R<sub>AB</sub> = (6 &times; 6) / (6 + 6) = 36 / 12 = 3.0 &Omega;</b>.</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q99: Two heating elements R<sub>1</sub>, R<sub>2</sub> operate on voltage V. Prove ratio of parallel to series heating rates is H<sub>p</sub> / H<sub>s</sub> = (R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup> / (R<sub>1</sub> R<sub>2</sub>) >= 4.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Parallel Rate:</b> H<sub>p</sub> = V<sup>2</sup> / R<sub>p</sub> = V<sup>2</sup> [(R<sub>1</sub> + R<sub>2</sub>) / (R<sub>1</sub> R<sub>2</sub>)].<br><b>2. Series Rate:</b> H<sub>s</sub> = V<sup>2</sup> / R<sub>s</sub> = V<sup>2</sup> / (R<sub>1</sub> + R<sub>2</sub>).<br><b>3. Ratio:</b> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">H<sub>p</sub></span><span style=\"padding: 0 2px; display: inline-block;\">H<sub>s</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sup>2</sup> (R<sub>1</sub> + R<sub>2</sub>) / (R<sub>1</sub> R<sub>2</sub>)</span><span style=\"padding: 0 2px; display: inline-block;\">V<sup>2</sup> / (R<sub>1</sub> + R<sub>2</sub>)</span></span> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub> R<sub>2</sub></span></span></b>.<br>Since (R<sub>1</sub> + R<sub>2</sub>)<sup>2</sup> - 4 R<sub>1</sub> R<sub>2</sub> = (R<sub>1</sub> - R<sub>2</sub>)<sup>2</sup> &ge; 0 &rArr; <b>H<sub>p</sub> / H<sub>s</sub> &ge; 4</b> (Minimum ratio = 4 when R<sub>1</sub> = R<sub>2</sub>).</div>\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.2px solid rgba(255, 145, 0, 0.25); border-radius: 10px; padding: 16px; margin-bottom: 18px;\">\n    <h3 style=\"color: #FF9100; margin: 0 0 12px 0; font-size: 16.5px; font-weight: bold; line-height: 1.5;\">Q100: Three batteries &#949;<sub>1</sub>=6 V (1 &Omega;), &#949;<sub>2</sub>=4 V (2 &Omega;), &#949;<sub>3</sub>=2 V (1 &Omega;) are in parallel across load R=5 &Omega;. Find equivalent EMF, internal r, and load current.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF9100; padding: 12px 14px; border-radius: 4px; color: #FFFFFF; font-size: 15px; line-height: 1.65;\">\n      <b style=\"color: #FF9100; display: block; margin-bottom: 6px;\">Answer:</b>\n      <div style=\"color: #FFFFFF;\"><b>1. Equivalent Internal Resistance:</b><br>1/r<sub>eq</sub> = 1/r<sub>1</sub> + 1/r<sub>2</sub> + 1/r<sub>3</sub> = 1/1 + 1/2 + 1/1 = 2.5 &Omega;<sup>-1</sup> = 5/2 &Omega;<sup>-1</sup> &rArr; <b>r<sub>eq</sub> = 2/5 = 0.40 &Omega;</b>.<br><br><b>2. Equivalent EMF:</b><br>&#949;<sub>eq</sub> / r<sub>eq</sub> = &#949;<sub>1</sub>/r<sub>1</sub> + &#949;<sub>2</sub>/r<sub>2</sub> + &#949;<sub>3</sub>/r<sub>3</sub> = 6/1 + 4/2 + 2/1 = 6 + 2 + 2 = 10 A.<br><b>&#949;<sub>eq</sub> = 10 &times; r<sub>eq</sub> = 10 &times; 0.40 = 4.0 V</b>.<br><br><b>3. Load Current I:</b><br>I = &#949;<sub>eq</sub> / (R + r<sub>eq</sub>) = 4.0 / (5.0 + 0.40) = 4.0 / 5.4 = <b>0.741 A</b>.<br><br><b>4. Terminal Voltage V:</b><br>V = I R = 0.741 &times; 5.0 = <b>3.70 V</b>.</div>\n    </div>\n  </div>\n</div>";

